-- Etsy Ledger lines (etsy_ledger_lines) — 2573 rows across 7 real
-- monthly exports (etsy_statement_2026_1.csv .. _7.csv, Jan-Jul 2026),
-- extracted programmatically (not hand-typed) from the exact CSVs you
-- uploaded, using the SAME number/date parsing the app's own CSV Upload
-- importer uses (strip currency symbol + commas, "--" -> NULL, parse
-- "Month D, YYYY" dates) — see src/app/dashboard/csv-upload/actions.ts
-- and src/lib/statement-import/tables.ts's "etsy_ledger" config.
--
-- Date range covered: 2026-01-01 .. 2026-07-31.
--
-- No unique constraint on this table, so re-running this file (or
-- having already loaded some/all of this via the CSV Upload screen)
-- would duplicate rows. This wraps the load in a scoped
-- DELETE-then-INSERT, same pattern as the eBay Tax Invoice Detail SQL
-- delivered earlier today — safe to run more than once.

BEGIN;

DELETE FROM etsy_ledger_lines
WHERE company_id = (SELECT id FROM companies WHERE name = 'Nyko Mart')
  AND txn_date >= '2026-01-01'
  AND txn_date <= '2026-07-31';


-- Sanity check — should read 2573 rows, 2026-01-01 .. 2026-07-31.
SELECT count(*) AS total_rows, min(txn_date) AS earliest, max(txn_date) AS latest,
       count(*) FILTER (WHERE order_number IS NOT NULL) AS rows_with_order_number
FROM etsy_ledger_lines
WHERE company_id = (SELECT id FROM companies WHERE name = 'Nyko Mart');

COMMIT;
